def process_amazon_batch(
    identifiers: list[str], stage_import_by_identifier: dict[str, bool] | None = None
) -> None:
    """
    Fetch products for identifiers and cache each product. Only products with a
    requested identifier marked for import are queued for import staging.
    """
    logger.info(f"process_amazon_batch(): {len(identifiers)} items")
    try:
        products = web.amazon_api.get_products(identifiers, serialize=True)
        # stats_ol_affiliate_amazon_imports - Open Library - Dashboards - Grafana
        # http://graphite.us.archive.org Metrics.stats.ol...
        stats.increment(
            "ol.affiliate.amazon.total_items_fetched",
            n=len(products),
        )
    except Exception:
        logger.exception(f"amazon_api.get_products({identifiers}, serialize=True)")
        return

    for product in products:
        cache_key = make_cache_key(product)  # isbn_13 or non-ISBN-10 ASIN.
        cache.memcache_cache.set(  # Add each product to memcache
            f'amazon_product_{cache_key}', product, expires=WEEK_SECS
        )

    # Only proceed if config finds infobase db creds
    if not config.infobase.get('db_parameters'):  # type: ignore[attr-defined]
        logger.debug("DB parameters missing from affiliate-server infobase")
        return

    def should_stage(product: dict) -> bool:
        if stage_import_by_identifier is None:
            return True
        product_identifiers = {
            str(identifier)
            for field_name in ("isbn_10", "isbn_13")
            for identifier in product.get(field_name, []) or []
        }
        for source_record in product.get("source_records", []) or []:
            if source_record.startswith("amazon:"):
                product_identifiers.add(source_record.partition(":")[2])
        return any(
            stage_import_by_identifier.get(identifier, False)
            for identifier in product_identifiers
        )

    books = [
        clean_amazon_metadata_for_load(product)
        for product in products
        if should_stage(product)
    ]

    if books:
        stats.increment(
            "ol.affiliate.amazon.total_items_batched_for_import",
            n=len(books),
        )
        get_current_amazon_batch().add_items(
            [
                {'ia_id': b['source_records'][0], 'status': 'staged', 'data': b}
                for b in books
            ]
        )


