def amazon_lookup(site, stats_client, logger) -> None:
    """
    A separate thread of execution that uses the time up to API_MAX_WAIT_SECONDS to
    create a list of isbn_10s that is not larger than API_MAX_ITEMS_PER_CALL and then
    passes them to process_amazon_batch()
    """
    stats.client = stats_client
    web.ctx.site = site

    while True:
        start_time = time.time()
        identifiers: set[str] = set()  # no duplicates in the batch
        stage_import_by_identifier: dict[str, bool] = {}
        while len(identifiers) < API_MAX_ITEMS_PER_CALL and seconds_remaining(
            start_time
        ):
            try:  # queue.get() will block (sleep) until successful or it times out
                item = web.amazon_queue.get(timeout=seconds_remaining(start_time))
                identifiers.add(item.identifier)
                stage_import_by_identifier[item.identifier] = (
                    stage_import_by_identifier.get(item.identifier, False)
                    or item.stage_import
                )
            except queue.Empty:
                pass
        logger.info(f"Before amazon_lookup(): {len(identifiers)} items")
        if identifiers:
            time.sleep(seconds_remaining(start_time))
            try:
                process_amazon_batch(list(identifiers), stage_import_by_identifier)
                logger.info(f"After amazon_lookup(): {len(identifiers)} items")
            except Exception:
                logger.exception("Amazon Lookup Thread died")
                stats_client.incr("ol.affiliate.amazon.lookup_thread_died")


